config/dev03_wp04_l2_l3_meteorology_read.content:
{
  "schema_version": 2,
  "contract_version": "l2-l3-meteorology-read-contract-v2",
  "status": "audit_a_r_b_repair_candidate",
  "date": "2026-09-29",
  "development_phase": "DEV-03",
  "work_package": "DEV03-WP04",
  "implementation_step": "WP04-AUDIT-A-R-B",
  "predecessor_contract": "phase3-archive-interface-gate-v1",
  "purpose": "Provider-format-independent, causally explicit L2-to-L3 meteorology read schema for BrokerSessionV1/BrokerQueryV1 adapters. This contract defines the six logical evidence views only; it does not implement adapter selection, broker orchestration, analysis, persistence, or L4/L5 decisions.",
  "authorities": [
    "config/dev03_wp02_l1_l2_successor_design_v1.json",
    "config/dev03_prep05_migration_topology_v1.json",
    "config/dev03_prep06_l3_broker_api_v1.json",
    "config/dev03_prep07_acceptance_resource_budget_v1.json",
    "config/dev03_wp04_fine_plan_v1.json",
    "config/dev03_wp04_audit_a_v1.json"
  ],
  "immutable_boundaries": {
    "archives_read_only": [
      "v1",
      "v2",
      "v3",
      "v4",
      "v5",
      "v6"
    ],
    "one_as_of_required": true,
    "whole_occurrence_v5_v6_precedence": true,
    "mixed_v5_v6_field_composition_forbidden": true,
    "missing_identity_inference_forbidden": true,
    "missing_interval_inference_forbidden": true,
    "typed_missingness_numeric_substitution_forbidden": true,
    "operational_authority_unchanged": "v16-c3-v9",
    "l4_l5_cutover_authorized": false
  },
  "queryable_entities": [
    "wind_u_10m",
    "wind_v_10m",
    "wind_speed_10m",
    "wind_direction_10m",
    "wind_gust_10m",
    "air_temperature_2m",
    "dewpoint_temperature_2m",
    "relative_humidity_2m",
    "mean_sea_level_pressure",
    "surface_pressure",
    "total_precipitation",
    "total_cloud_cover",
    "surface_downward_shortwave_direct",
    "surface_downward_shortwave_diffuse",
    "surface_downward_shortwave",
    "cape",
    "cin",
    "convective_precipitation"
  ],
  "state_families": {
    "identity_completeness": [
      "native_exact",
      "legacy_exactly_reconstructable",
      "legacy_partial",
      "invalid"
    ],
    "interval_status": [
      "resolved",
      "point",
      "unknown",
      "ambiguous",
      "invalid"
    ],
    "availability_status": [
      "received",
      "unsupported_by_provider_or_product",
      "intentionally_not_applicable",
      "not_requested_by_policy",
      "not_yet_published",
      "fetch_error",
      "unknown_or_ambiguous"
    ],
    "source_health": [
      "successor_native",
      "legacy_only",
      "degraded_fallback_legacy",
      "invalid_no_safe_input"
    ],
    "ensemble_completeness": [
      "complete",
      "partial",
      "not_applicable",
      "invalid"
    ]
  },
  "public_query_boundary": {
    "allowed_project_level_dimensions": [
      "entity_ids",
      "valid_time_window",
      "run_selector",
      "lead_selector",
      "source_selector",
      "native_variant_selector",
      "interval_selector",
      "ensemble_projection"
    ],
    "forbidden_provider_format_dimensions": [
      "provider_filename",
      "provider_url",
      "source_url",
      "download_url",
      "grib_key",
      "grib_message_index",
      "provider_native_path",
      "archive_path",
      "parquet_path",
      "archive_version_selector"
    ],
    "caller_may_select_archive_source": false,
    "provider_format_agnostic": true
  },
  "layer_boundary": {
    "permitted": [
      "semantic/entity lookup",
      "causal record and field selection",
      "typed missingness propagation",
      "native identity and interval preservation",
      "ensemble source-set atomic projection",
      "selection/audit diagnostics"
    ],
    "forbidden": [
      "kite suitability",
      "safety authorization",
      "GREEN/RED or traffic-light decisions",
      "notification eligibility or dispatch",
      "cross-field meteorological derivation such as wind speed/direction from U/V",
      "cross-model skill weighting",
      "model-family contribution selection for final analysis",
      "calibration fitting",
      "operational v3/v6 cutover"
    ]
  },
  "legacy_policy": {
    "allowed_identity_states": [
      "legacy_exactly_reconstructable",
      "legacy_partial",
      "invalid"
    ],
    "exact_only_rule": "Legacy adapters may populate only values exactly derivable from persisted evidence.",
    "partial_rule": "Missing native identity remains null with field_identity_completeness_status=legacy_partial; consumers that require the dimension must reject rather than infer it.",
    "convective_precipitation": {
      "capable_legacy_models": [
        "ICON-D2",
        "ICON-EU",
        "GFS"
      ],
      "capable_status": "not_requested_by_policy",
      "unsupported_models": [
        "ECMWF-IFS",
        "GEFS-control",
        "NOAA_GEFS_FULL"
      ],
      "unsupported_status": "unsupported_by_provider_or_product",
      "total_precipitation_substitution_forbidden": true,
      "cape_cin_substitution_forbidden": true
    }
  },
  "successor_policy": {
    "required_archive_version": "v6",
    "normal_identity_state": "native_exact",
    "integrity_validation_required_before_exposure": true,
    "migration_source_occurrence_id_required_for_linked_replacement": true
  },
  "normalized_interval_rules": {
    "resolved": "interval_start_utc, interval_end_utc and non-negative interval_seconds are required.",
    "point": "interval_start_utc and interval_end_utc are required and equal; interval_seconds must be 0.",
    "unknown": "normalized interval boundaries and interval_seconds must remain null.",
    "ambiguous": "normalized interval boundaries and interval_seconds must remain null.",
    "invalid": "normalized interval boundaries and interval_seconds must remain null; native conflicting evidence remains in native identity columns/provenance."
  },
  "field_native_exact_required_non_null": [
    "parameter_native",
    "unit_native",
    "type_of_level_native",
    "level_native",
    "step_type_native"
  ],
  "logical_views": {
    "l3_forecast_records_v1": {
      "role": "causal forecast occurrence identity",
      "additional_columns_forbidden": true,
      "columns": {
        "logical_record_id": {
          "type": "string",
          "nullable": false
        },
        "revision_event_id": {
          "type": "string",
          "nullable": false
        },
        "migration_source_occurrence_id": {
