{
  "schema_version": 1,
  "artifact_version": "dev03-wp12-lifecycle-contract-v1",
  "architecture_layer": [
    "L1",
    "L2"
  ],
  "introduced_in_development_phase": "DEV-03",
  "lifecycle": "candidate",
  "supersedes_or_null": null,
  "compatibility_dependencies": [
    {
      "path": "config/dev03_wp12_format_contract_v1.json",
      "sha256": "f664b9a5d13c5c557da9f9632dc3bc9aba0707fcb336e0021ec49f09f4fa7de2"
    },
    {
      "path": "config/dev03_wp12_domain_registry_v2.json",
      "sha256": "d05841457438ccffd88b2fbd434a3697a672d3b6e4ed261e94cbc983804e4257"
    },
    {
      "path": "config/weather_archive_v6.json",
      "sha256": "e6bcf68c707faeabf55dec72c31a4f548383c66b6d86b407d6419a99e793c882"
    }
  ],
  "audit_lineage": [],
  "status": "inactive_reference_contract",
  "limits": {
    "max_sites_per_job": 4,
    "max_member_fields": 4096,
    "max_batch_rows": 256,
    "max_payload_bytes": 8388608,
    "max_decoded_bytes": 33554432,
    "max_fragment_bytes": 16777216,
    "max_total_decoded_bytes": 67108864,
    "max_raw_objects": 64,
    "max_fragments": 64,
    "max_runtime_seconds": 30,
    "max_peak_rss_bytes": 536870912,
    "history_requests_per_job": 8,
    "max_history_seconds_per_request": 86400,
    "incremental_bytes_per_year": 4294967296
  },
  "temporal_rules": {
    "configuration_validity": "Check interpretation clock, never infer station installation or historical measurement coverage from registry valid_from. Native identity and original clocks remain unchanged.",
    "public_capture": "Original receipt retrieval time; immutable per revision, never publication/run/validity/private import time.",
    "private_receipt": "New private receipt >= original capture and verified time. Never backdate migrated imports.",
    "interpretation": "Clock >= private receipt; bound to configuration hash valid at this clock.",
    "native_publication": "Can establish historical public availability only with hash-bound pointer proving exact published_at; run/valid time alone never publication evidence. Otherwise original observed public capture is conservative availability.",
    "forecast_as_of": "Two views: public_reconstruction uses proven public availability; private_operational additionally requires private receipt and interpretation <= as_of.",
    "truth_as_of": "Truth revision must be publicly/private visible by fit cutoff in causal view; retrospective_latest is a distinct frozen cohort, not an as_of reconstruction. Observations after prediction issue are targets only, never predictors.",
    "revisions": "Distinct provider revisions remain distinct immutable transfers; select latest visible by availability then source_revision; ambiguous simultaneous conflicting revisions fail closed."
  },
  "storage_reference": {
    "scope": "Temporary-directory contract proof; production archive/Parquet writer remains WP14 work.",
    "identity": "SHA256 of complete transfer envelope + native fields + lifecycle receipt; raw/fragment physical hashes are already bound by envelope. No volatile telemetry inside.",
    "publication": "POSIX flock; verified fsynced complete staging directory -> atomic rename -> parent fsync; no partial member set visible.",
    "replay": "Validate existing immutable bytes and inventory; same identity adds zero files/bytes; corruption rejects without repair.",
    "rollback": "Stop successor writes; keep evidence and legacy view; no active operational pointer here."
  },
  "projection": {
    "logical_schema": "config/schemas/dev03_wp12_read_field_v1.schema.json",
    "physical_layout": "long rows, partition by configuration/site/record_kind/UTC valid-end date; no global default location",
    "timestamps": "Arrow timestamp[us,tz=UTC]; reject nonzero submicrosecond precision loss; retain original text in native sidecar",
    "row_batches_max": 256,
    "compression": "zstd level 3; authoritative native sidecar retained; physical implementation/measurement WP14-I06",
    "extensions": "Namespaced optional; unknown required capabilities rejected before publication"
  },
  "deployment_sequence": [
    {
      "step": "WP13-I05",
      "action": "Implement configurable writer offline; collection_enabled=false."
    },
    {
      "step": "WP13-I06",
      "action": "Test bounded history and legacy compatibility; writer remains disabled."
    },
    {
      "step": "WP14-I06/I07",
      "action": "Implement receiver, normalizer, atomic archive and causal readers."
    },
    {
      "step": "WP14-I08",
      "action": "Deploy accepting consumer and verify negotiated contracts before writer."
    },
    {
      "step": "WP15-I01",
      "action": "Bounded real transfer canary; prove metadata, budgets, replay and rollback."
    },
    {
      "step": "WP15-I02",
      "action": "Enable routine writer only after canary acceptance."
    },
    {
      "step": "WP15-I03/I04",
      "action": "Reproject preserved raw and extend bounded historical/regional capture."
    }
  ],
  "history_jobs": {
    "identity": "provider/site/station/sensor + explicit UTC window + request key; cursor persists after verified atomic receipt only",
    "retry": "Retry same bounded window after transient failure; never advance cursor on failed integrity; no all-history loop in one job",
    "budget": "<=8 provider requests and <=24h per request; site/member/byte/runtime/RSS limits apply too"
  },
  "storage_growth": {
    "cap_bytes_per_year": 4294967296,
    "accounting": "All new immutable raw, native fragments, canonical projections and receipts; shared parents counted once. Replay counted zero. 365*measured daily footprint, separate historical imported bytes.",
    "activation_gate": "WP15 real canary must measure representative daily raw/projection growth and matched projection ratio <=1.5. Fixture growth is not live provider proof. Exceedance requires scoped budget successor or cadence/scope reduction, never silently deleting members."
  },
  "required_core_semantics_open": [],
  "optional_field_semantics_open": [
    "WeatherLink historical temperature/RH operators",
    "pressure variant/reduction",
    "provider extraction grid absent in legacy payload"
  ],
  "scientific_gate": "OPEN",
  "outbound_requests_in_L3": 0
}

